// WWE calendar: weekly programming and Premium Live Events (PLEs).
// DATA QUALITY NOTE: show start/end years and PLE months are curated from general wrestling
// history knowledge and generated by simple rules (e.g. "last Saturday of January"). They are
// approximate by design - exact historical dates/venues are NOT claimed. Each entry carries
// `confidence` so the UI/reports can be honest about it.

const DAY_MS = 86400000;
export const WEEKDAY = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

/** absolute day index (0 = Jan 1 of startYear) -> Date (UTC) */
export const dateOf = (day, startYear) => new Date(Date.UTC(startYear, 0, 1) + day * DAY_MS);
export const weekdayOf = (day, startYear) => dateOf(day, startYear).getUTCDay();

/** n-th weekday of month; n = -1 means last. month is 0-11. returns day-of-month */
export function nthWeekday(year, month, weekday, n) {
  if (n > 0) {
    const first = new Date(Date.UTC(year, month, 1)).getUTCDay();
    return 1 + ((weekday - first + 7) % 7) + (n - 1) * 7;
  }
  const last = new Date(Date.UTC(year, month + 1, 0));
  return last.getUTCDate() - ((last.getUTCDay() - weekday + 7) % 7);
}

