// Known recent WrestleMania Saturday-night dates (month index, day-of-month); other years use the weekday rule.
const WM_OVERRIDES = { 2019: [3, 6], 2020: [3, 4], 2021: [3, 10], 2022: [3, 2], 2023: [3, 1], 2024: [3, 6], 2025: [3, 19], 2026: [3, 18] };

function pleDate(def, year) {
  if (def.id === 'wrestlemania' && WM_OVERRIDES[year]) return Date.UTC(year, WM_OVERRIDES[year][0], WM_OVERRIDES[year][1]);
  return Date.UTC(year, def.month, nthWeekday(year, def.month, def.weekday, def.n));
}

/** All PLEs in a calendar year as [{id,name,dayOfYear,tier,...}] sorted by date. */
export function plesInYear(year) {
  const out = [];
  for (const def of PLE_DEFS) {
    if (year < def.from || year > def.to) continue;
    const t = pleDate(def, year);
    const dayOfYear = Math.round((t - Date.UTC(year, 0, 1)) / DAY_MS);
    const number = def.numbered ? year - 1984 : null;
    out.push({ ...def, year, dayOfYear, displayName: def.numbered ? `WrestleMania ${number}` : def.name, number });
  }
  return out.sort((a, b) => a.dayOfYear - b.dayOfYear);
}

/** Events happening on an absolute day for the given brand. */
export function eventsOn(day, startYear, brand) {
  const d = dateOf(day, startYear);
  const year = d.getUTCFullYear();
  const dow = d.getUTCDay();
  const out = [];
  const doy = Math.round((d.getTime() - Date.UTC(year, 0, 1)) / DAY_MS);
  for (const ple of plesInYear(year)) {
    if (ple.dayOfYear === doy && (!ple.brandOnly || ple.brandOnly === brand)) out.push({ kind: 'ple', ...ple });
  }
  for (const w of WEEKLY) {
    if (year >= w.from && year <= w.to && w.weekday === dow && (!brand || w.brand === brand)) {
      // a PLE weekend replaces the weekly show on the same night for that brand
      if (!out.some((e) => e.kind === 'ple' && e.dayOfYear === doy)) out.push({ kind: 'weekly', ...w, displayName: w.name });
    }
  }
  return out;
}

/** next event (weekly or PLE) on/after `fromDay` for a brand */
export function nextEvent(fromDay, startYear, brand, horizon = 400) {
  for (let i = 0; i <= horizon; i++) {
    const ev = eventsOn(fromDay + i, startYear, brand);
    if (ev.length) return { day: fromDay + i, ...ev.sort((a, b) => (b.tier || 0) - (a.tier || 0))[0] };
  }
  return null;
}

/** default brand for a year/background */
export function brandsInYear(year) {
  const set = new Set();
  for (const w of WEEKLY) if (year >= w.from && year <= w.to) set.add(w.brand);
  return [...set];
}

export function formatDate(day, startYear) {
  const d = dateOf(day, startYear);
  return d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
}
